public static class RaceMenuImport {
 public sealed record Result(FaceScene Scene,List<string> Messages,int MorphsApplied,int SculptVertices){public string Status=>Messages.Count==0?"Loaded":"Partial";public string Summary=>Status+" · custom morph applications: "+MorphsApplied+" · sculpt vertices: "+SculptVertices+"\n"+string.Join("\n",Messages);}
 static string N(string s)=>s.Replace('\\','/').TrimStart('/').ToLowerInvariant();
 public static Result Load(string path,string dataRoot,bool allowDeclaredReferenceDifference=false,string? exportedNif=null){if(new FileInfo(path).Length>16*1024*1024)throw new InvalidDataException("jslot exceeds 16 MiB");using var document=JsonDocument.Parse(File.ReadAllText(path),new JsonDocumentOptions{MaxDepth=48});var j=document.RootElement;if(j.ValueKind!=JsonValueKind.Object||!j.TryGetProperty("version",out var version)||version.GetProperty("formatVersion").GetInt32()!=3||version.GetProperty("signature").GetUInt32()!=1163086675||!j.TryGetProperty("headParts",out var headParts)||headParts.ValueKind!=JsonValueKind.Array||headParts.GetArrayLength()>128)throw new InvalidDataException("Unsupported/damaged RaceMenu jslot schema (expected SKSE format 3)");
 var resources=new GameResources(dataRoot);var notes=new List<string>();var db=new HeadPartRecords(resources);var ids=new List<string>();foreach(var h in headParts.EnumerateArray()){string? id=null;if(h.TryGetProperty("formIdentifier",out var identifier))id=identifier.GetString();else if(h.TryGetProperty("formId",out var raw)&&j.TryGetProperty("mods",out var mods)){uint value=raw.GetUInt32();foreach(var mod in mods.EnumerateArray())if(mod.GetProperty("index").GetUInt32()==(value>>24==0xfe?0xfe000|((value>>12)&0xfff):value>>24))id=mod.GetProperty("name").GetString()+"|"+(value&(value>>24==0xfe?0xfffu:0xffffffu)).ToString("X6");}if(id==null){notes.Add("HeadPart identifier unavailable; no runtime FormID guessing.");continue;}ids.Add(HeadPartRecords.Canonical(id));}
 foreach(var id in ids)db.Load(id.Split('|')[0]);string? headTexture=null;if(j.TryGetProperty("actor",out var actor)&&actor.TryGetProperty("headTexture",out var textureId)&&textureId.ValueKind==JsonValueKind.String){headTexture=textureId.GetString();if(!string.IsNullOrWhiteSpace(headTexture))db.Load(HeadPartRecords.Canonical(headTexture).Split('|')[0]);}
 resources.Configure(db.LoadedPlugins);if(resources.ActivePlugins.Count>0)db.Overrides(resources.ActivePlugins);

 var all=new List<HeadPartRecords.Record>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);void Add(string id,int depth){if(depth>16||all.Count>=128)throw new InvalidDataException("HeadPart extra/cycle budget");if(!seen.Add(id))return;var rec=db.Get(id);if(rec==null){var generated=GeneratedHeadParts.Resolve(id,resources,notes);if(generated.Count>0){all.AddRange(generated);return;}}if(rec==null||rec.Kind!="HDPT"||(rec.Flags&0x20)!=0){notes.Add("HDPT unavailable/deleted: "+id);return;}all.Add(rec);foreach(var field in rec.Fields.Where(f=>f.type=="HNAM"&&f.data.Length==4))Add(db.Reference(rec.Source,BitConverter.ToUInt32(field.data)),depth+1);}
 foreach(var id in ids)Add(id,0);
 if(exportedNif!=null){var exported=ExportedFace.Inspect(exportedNif,resources);foreach(var shape in exported.Parts){var records=GeneratedHeadParts.Resolve("ErinRace.esm|000000",resources,notes,shape.Name);if(records.Count==0)continue;uint type=records[0].Number("PNAM");var oldIds=all.Where(r=>r.Fields.Any(f=>f.type=="DSGN")&&r.Number("PNAM")==type).Select(r=>r.Id).ToList();all.RemoveAll(r=>oldIds.Any(id=>r.Id==id||r.Id.StartsWith(id+"#",StringComparison.Ordinal)));records[0].Id="exported:"+shape.Name;all.AddRange(records);}}
 var heads=all.Where(r=>r.Number("PNAM")==1&&r.Text("MODL").Length>0).ToList();if(heads.Count!=1)throw new InvalidDataException("A unique face HDPT could not be resolved. "+string.Join(" / ",notes.Concat(resources.Notes)));var faceRecord=heads[0];int faceFlags=faceRecord.Fields.FirstOrDefault(f=>f.type=="DATA").data?.FirstOrDefault()??0;string gender=(faceFlags&6)==4?"female":(faceFlags&6)==2?"male":"unknown";if(gender=="unknown")notes.Add("HeadPart sex flags are ambiguous; sex-specific custom slider mappings were not guessed.");
 string? facePath=resources.Mesh(faceRecord.Text("MODL"));if(facePath==null){resources.Missing("meshes/"+faceRecord.Text("MODL"));throw new FileNotFoundException("Base face resource unavailable. "+string.Join("\n",resources.Notes));}
 notes.Add("Face backing file: "+GameResources.BackingPath(facePath));var scene=FaceScene.Load(facePath,resources.Root,resources);scene.JslotPath=Path.GetFullPath(path);scene.JslotRoot=resources.Root;scene.JslotReferenceConfirmed=allowDeclaredReferenceDifference;int morphsApplied=0,sculptVertices=0;var custom=j.TryGetProperty("morphs",out var morphs)&&morphs.TryGetProperty("custom",out var cm)&&cm.ValueKind==JsonValueKind.Array?cm.EnumerateArray().ToList():[];if(custom.Count>2048)throw new InvalidDataException("Custom morph count limit");var customNames=new HashSet<string>(StringComparer.Ordinal);foreach(var m in custom){string? name=m.GetProperty("name").GetString();if(string.IsNullOrWhiteSpace(name)||name.Length>512||name.Contains('\0')||!customNames.Add(name))throw new InvalidDataException("Invalid/duplicate custom morph");}if(morphs.ValueKind==JsonValueKind.Object&&morphs.TryGetProperty("sculpt",out var sculptList)&&sculptList.ValueKind==JsonValueKind.Array){var uniqueHosts=new HashSet<string>();foreach(var host in sculptList.EnumerateArray())if(!uniqueHosts.Add(N(host.GetProperty("host").GetString()??"")))throw new InvalidDataException("Duplicate Sculpt host");}
 var plugins=all.Select(r=>r.Source).Concat(ids.Select(id=>id.Split('|')[0])).Distinct(StringComparer.OrdinalIgnoreCase).ToList();var maps=ReadMaps(resources,plugins,gender,notes);var processed=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var sculptHosts=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
 foreach(var record in all.OrderBy(r=>r==faceRecord?0:1)){if(scene.Parts.Count>=32){notes.Add("HeadPart limit reached; remaining parts omitted.");break;}
 uint type=record.Number("PNAM");string model=record.Text("MODL");if(model.Length==0)continue;string? file=resources.Mesh(model);if(file==null){resources.Missing("meshes/"+model);continue;}if(!processed.Add(file))continue;int before=scene.Parts.Count;if(!file.Equals(facePath,StringComparison.OrdinalIgnoreCase))try{scene.AddNif(file,type==3);}catch(Exception e){notes.Add("NIF "+model+": "+e.Message);continue;}
 var parts=scene.Parts.Where(p=>p.Source.Equals(Path.GetFullPath(file),StringComparison.OrdinalIgnoreCase)).ToList();var tris=record.Tris();TriFace? chargen=null;if(tris.TryGetValue(2,out var cg)){string? cp=resources.Mesh(cg);if(cp!=null)try{chargen=TriFace.Read(cp);}catch(Exception e){notes.Add("Chargen TRI "+cg+": "+e.Message);}else resources.Missing("meshes/"+cg);}
 var extraMorphs=new List<TriFace>();if(chargen!=null){extraMorphs.Add(chargen);foreach(var ext in Extensions(resources,plugins,tris.GetValueOrDefault(2)??"",notes)){try{var t=TriFace.Read(ext);if(!chargen.SameTopology(t)||(!chargen.SameReference(t)&&!allowDeclaredReferenceDifference)){notes.Add("Extension topology/reference rejected: "+ext);continue;}if(extraMorphs.Sum(m=>(long)m.Vertices.Length*m.Morphs.Count)+(long)t.Vertices.Length*t.Morphs.Count>4000000)throw new InvalidDataException("Custom TRI budget exceeded");extraMorphs.Add(t);}catch(Exception e){notes.Add("Extension TRI "+ext+": "+e.Message);}}}
 TriFace? combined=extraMorphs.FirstOrDefault()?.Clone();if(combined!=null){foreach(var extra in extraMorphs.Skip(1))combined.AddMorphs(extra,allowDeclaredReferenceDifference);notes.AddRange(combined.Warnings.Select(w=>model+": "+w));}
 foreach(var part in parts){part.HeadPartId=record.Id;part.ConfiguredExtra=record.Id.Contains('#');part.DeclaredEditorId=record.Text("EDID");part.HeadPartType=type;part.LogicalModel=model;
  // Bind expression morphs before changing the neutral reference. No count-only acceptance.
  if(tris.TryGetValue(1,out var expression)){string? ep=resources.Mesh(expression);if(ep!=null)try{var t=TriFace.Read(ep);if(scene.Compatibility(part,t).StartsWith("EXACT")||(allowDeclaredReferenceDifference&&scene.Compatibility(part,t).StartsWith("SCULPT"))){scene.AttachTri(part,t,allowDeclaredReferenceDifference);string? xp=resources.Mesh(Path.ChangeExtension(expression,null)+"_Extra.tri");if(xp!=null)scene.AttachTri(part,TriFace.Read(xp),allowDeclaredReferenceDifference);}else notes.Add("Expression TRI requires explicit correspondence confirmation: "+expression);}catch(Exception e){notes.Add("Expression TRI: "+e.Message);}else resources.Missing("meshes/"+expression);}
  string match=chargen==null?"missing":scene.Compatibility(part,chargen);bool verified=chargen!=null&&(match.StartsWith("EXACT")||(allowDeclaredReferenceDifference&&match.StartsWith("SCULPT")));if(verified&&match.StartsWith("SCULPT"))notes.Add("Confirmed declared HDPT vertex correspondence with differing reference geometry: "+part.Name);if(chargen!=null&&!verified)notes.Add("Chargen vertex correspondence not proven: "+part.Name+" / "+tris.GetValueOrDefault(2));
  var neutral=(Vector3[])part.Reference.Clone();if(verified){morphsApplied+=DefaultFaceMorphs.Apply(morphs,extraMorphs,neutral,notes,part.Name);foreach(var entry in custom){string name=entry.GetProperty("name").GetString()??"";double value=entry.GetProperty("value").GetDouble();if(!double.IsFinite(value)||Math.Abs(value)>20){notes.Add("Unsupported custom value: "+name);continue;}if(value==0)continue;if(!maps.TryGetValue(name,out var map)){notes.Add("Slider mapping unavailable: "+name);continue;}string target;double gain;if(map.kind.Equals("Preset",StringComparison.OrdinalIgnoreCase)){if(value<0||value!=Math.Truncate(value)){notes.Add("Invalid preset slider: "+name);continue;}target=map.lower+((int)value).ToString(CultureInfo.InvariantCulture);gain=1;}else{target=value<0?map.lower:map.upper;gain=Math.Abs(value);}if(target.Equals("None",StringComparison.OrdinalIgnoreCase))continue;bool applied=false;if(combined!=null&&combined.Morphs.TryGetValue(target,out var delta)){if(delta.Any(d=>d.LengthSquared>1e-16)){for(int i=0;i<neutral.Length;i++)neutral[i]+=new Vector3((float)delta[i].X,(float)delta[i].Y,(float)delta[i].Z)*(float)gain;morphsApplied++;}applied=true;}if(!applied)notes.Add("Custom TRI morph unavailable: "+name+" -> "+target+" / "+part.Name);}
   if(morphs.ValueKind==JsonValueKind.Object&&morphs.TryGetProperty("sculpt",out var sc)&&sc.ValueKind==JsonValueKind.Array){if(sc.GetArrayLength()>128)throw new InvalidDataException("Sculpt host count");double divisor=morphs.TryGetProperty("sculptDivisor",out var div)?div.GetDouble():10000;if(!double.IsFinite(divisor)||divisor<=0)throw new InvalidDataException("Invalid sculpt divisor");foreach(var host in sc.EnumerateArray()){string hostName=host.GetProperty("host").GetString()??"";if(N(hostName)!=N(tris.GetValueOrDefault(2)??""))continue;int vertices=host.GetProperty("vertices").GetInt32();if(vertices!=neutral.Length){notes.Add("Sculpt vertex count rejected: "+hostName);continue;}var deltas=host.GetProperty("data");if(deltas.ValueKind!=JsonValueKind.Array||deltas.GetArrayLength()>neutral.Length)throw new InvalidDataException("Sculpt entry count");var indexes=new HashSet<int>();var staged=new List<(int i,Vector3 delta)>();foreach(var row in deltas.EnumerateArray()){if(row.GetArrayLength()!=4)throw new InvalidDataException("Sculpt tuple");int index=row[0].GetInt32();var v=new Vector3((float)(row[1].GetDouble()/divisor),(float)(row[2].GetDouble()/divisor),(float)(row[3].GetDouble()/divisor));if(index<0||index>=neutral.Length||!indexes.Add(index)||!FaceScene.Finite(v)||v.Length()>1000)throw new InvalidDataException("Sculpt index/delta");staged.Add((index,v));}foreach(var (i,d) in staged)neutral[i]+=d;sculptVertices+=staged.Count(s=>s.delta.LengthSquared()>1e-16f);sculptHosts.Add(N(hostName));}}
  }part.IdentityReference??=(Vector3[])part.Reference.Clone();part.Reference=neutral;part.LastWeights=null;
  string generatedDiffuse=record.Text("DSDF");if(generatedDiffuse.Length>0){string? gp=resources.Texture(generatedDiffuse);if(gp!=null)try{scene.SetTexture(part,gp);}catch(Exception e){notes.Add("Runtime DDS: "+e.Message);}else resources.Missing(generatedDiffuse);}
  string? tid=record==faceRecord&&headTexture!=null?headTexture:record.Fields.Any(f=>f.type=="TNAM")?db.Reference(record.Source,record.Number("TNAM")):null;if(tid!=null){var tx=db.Get(tid);string tex=tx?.Text("TX00")??"";if(tex.Length>0){string? target=resources.Texture(tex);if(target!=null)try{scene.SetTexture(part,target);}catch(Exception e){notes.Add("DDS: "+e.Message);}else resources.Missing("textures/"+tex);}}
  if(record==faceRecord&&j.TryGetProperty("faceTextures",out var textures)&&textures.ValueKind==JsonValueKind.Array)foreach(var t in textures.EnumerateArray())if(t.GetProperty("index").GetInt32()==0){string tex=t.GetProperty("texture").GetString()??"";string? tp=resources.Texture(tex);if(tp!=null)try{scene.SetTexture(part,tp);}catch(Exception e){notes.Add("Face diffuse: "+e.Message);}else resources.Missing("textures/"+tex);}
 }
 }
 if(morphs.ValueKind==JsonValueKind.Object){if(morphs.TryGetProperty("sculpt",out var hosts)&&hosts.ValueKind==JsonValueKind.Array)foreach(var h in hosts.EnumerateArray())if(!sculptHosts.Contains(N(h.GetProperty("host").GetString()??"")))notes.Add("Sculpt not applied: "+h.GetProperty("host").GetString());}
 if(j.TryGetProperty("faceTextures",out var ft)&&ft.ValueKind==JsonValueKind.Array&&ft.EnumerateArray().Any(t=>t.GetProperty("index").GetInt32()!=0))notes.Add("Only diffuse faceTextures index 0 is rendered; normal/specular/tint slots are not composited.");if(actor.ValueKind==JsonValueKind.Object&&actor.TryGetProperty("hairColor",out var hc))FaceTint.ApplyHair(scene,hc.GetUInt32());if(j.TryGetProperty("tintInfo",out var tint)&&tint.ValueKind==JsonValueKind.Array)FaceTint.Apply(scene,tint,resources,notes);if(j.TryGetProperty("transforms",out _))notes.Add("RaceMenu node transforms are not applied.");if(j.TryGetProperty("bodyMorphs",out _))notes.Add("Body morphs and body weight interpolation are outside the face preview scope.");if(exportedNif!=null)ExportedFace.Apply(scene,exportedNif,notes);notes.Add("jslot does not establish current actor race/sex, runtime morph registration, lighting or final game facial blending.");notes.AddRange(resources.Notes);notes.AddRange(scene.Warnings);scene.Warnings.AddRange(notes.Distinct());scene.AutomaticSources.UnionWith(scene.Parts.Select(p=>p.Source));scene.ResourcePlugins=db.LoadedPlugins.ToList();foreach(var p in scene.Parts)p.AutoTexturePath=p.TexturePath;scene.InvalidateGeometry();scene.Apply(null);return new(scene,notes.Distinct().ToList(),morphsApplied,sculptVertices);
 }
 sealed record Slider(string kind,string lower,string upper);
 static Dictionary<string,Slider> ReadMaps(GameResources r,IEnumerable<string> plugins,string gender,List<string> notes){var maps=new Dictionary<string,Slider>(StringComparer.Ordinal);var ambiguous=new HashSet<string>(StringComparer.Ordinal);foreach(var plugin in plugins){string folder=r.PathFor("meshes/actors/character/facegenmorphs/"+plugin+"/sliders");if(!Directory.Exists(folder))continue;foreach(var f in Directory.EnumerateFiles(folder,"*.ini").Take(256)){if(new FileInfo(f).Length>2*1024*1024){notes.Add("Slider INI too large: "+f);continue;}string section="";foreach(var line in File.ReadLines(f)){var text=line.Trim();if(text.StartsWith('[')){section=text.Trim('[',']').ToLowerInvariant();continue;}if(section!=gender||text.StartsWith('#')||text.StartsWith(';'))continue;int equals=text.IndexOf('=');if(equals<0)continue;var values=text[(equals+1)..].Split(',').Select(v=>v.Trim()).ToArray();if(values.Length>=4&&values[1] is "Slider" or "Preset"){string name=text[..equals].Trim();var next=new Slider(values[1],values[2],values[3]);if(ambiguous.Contains(name))continue;if(maps.TryGetValue(name,out var existing)&&existing!=next){maps.Remove(name);ambiguous.Add(name);notes.Add("Ambiguous slider mappings skipped: "+name);}else maps[name]=next;}}}}return maps;}
 static IEnumerable<string> Extensions(GameResources r,IEnumerable<string> plugins,string chargen,List<string> notes){var files=new List<string>();foreach(var plugin in plugins){string path=r.PathFor("meshes/actors/character/facegenmorphs/"+plugin+"/morphs.ini");if(!File.Exists(path))continue;if(new FileInfo(path).Length>2*1024*1024)continue;foreach(var line in File.ReadLines(path)){string text=line.Trim();if(!text.StartsWith("extension",StringComparison.OrdinalIgnoreCase)||!text.Contains('='))continue;var names=text[(text.IndexOf('=')+1)..].Split(',').Select(x=>x.Trim()).ToArray();if(names.Length<2||N(names[0])!=N(chargen))continue;foreach(var name in names.Skip(1)){string? p=r.Mesh("actors/character/facegenmorphs/morphs/"+name);if(p!=null)files.Add(p);else r.Missing("meshes/actors/character/facegenmorphs/morphs/"+name);}}}return files.Distinct(StringComparer.OrdinalIgnoreCase);}
}
